/**
 * dunes: a real elevation field, baked and smoothed.
 *
 * Source: AWS Open Data terrain tiles (NASA/USGS SRTM + GMTED), terrarium PNG
 * at 31.1500, -3.9800, 3200 m across, 128×128 samples, smoothed with three passes of a
 * Gaussian (σ = 2.4) so the mesh carries rounded landforms instead of DEM spikes.
 * Raw range 16.7 … 221.6 m — the field is normalised to 0..1; the scene's `relief` sets the metres.
 * Rebuild: python3 scripts/bake-dem.py dunes terrarium 31.15 -3.98 3200 128
 */
export const DEM = {
  name: 'dunes',
  size: 128,
  spanMeters: 3200,
  source: 'terrarium',
  origin: [31.1500, -3.9800] as [number, number],
  data: '',
}
